def iter_kept_rollouts(jsonl_path: Path) -> Iterator[dict[str, Any]]:
    for line in jsonl_path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line:
            continue
        o = json.loads(line)
        if not o.get("kept"):
            continue
        if o.get("error"):
            continue
        if o.get("score") is None:
            continue
        yield o

app.persona.artifact_gen._strip_json_fen.source_code:
def _strip_json_fence(text: str) -> str:
    t = text.strip()
    m = re.match(r"^```(?:json)?\s*\n?", t, re.IGNORECASE)
    if m:
        t = t[m.end() :]
    if t.endswith("```"):
        t = t[: -3].rstrip()
    return t.strip()

