def build_alignment_presets(grid: dict[str, Any]) -> dict[str, dict[str, Any]]:
    """Nine classic alignments → steering recipe (trait_a, trait_b, alpha_a, alpha_b)."""
    corners = grid.get("corners") or {}

    def corner_alphas(cid: str) -> tuple[float, float]:
        b = corners.get(cid)
        if not b:
            return 0.0, 0.0
        c = _best_cell(b)
        return float(c.get("alpha_a", 0.0)), float(c.get("alpha_b", 0.0))

    lg_a, lg_b = corner_alphas("lawful_good")
    cg_a, cg_b = corner_alphas("chaotic_good")
    le_a, le_b = corner_alphas("lawful_evil")
    ce_a, ce_b = corner_alphas("chaotic_evil")

    # Rows: Lawful / Neutral / Chaotic. Cols: Good / Neutral / Evil.
    presets: dict[str, dict[str, Any]] = {
        "LG": {
            "label": "Lawful Good",
            "trait_a": "lawful",
            "trait_b": "good",
            "alpha_a": lg_a,
            "alpha_b": lg_b,
        },
        "NG": {
            "label": "Neutral Good",
            "trait_a": "lawful",
            "trait_b": "good",
            "alpha_a": 0.0,
            "alpha_b": lg_b,
        },
        "CG": {
            "label": "Chaotic Good",
            "trait_a": "chaotic",
            "trait_b": "good",
            "alpha_a": cg_a,
            "alpha_b": cg_b,
        },
        "LN": {
            "label": "Lawful Neutral",
            "trait_a": "lawful",
            "trait_b": "good",
            "alpha_a": lg_a,
            "alpha_b": 0.0,
        },
        "N": {
            "label": "True Neutral",
            "trait_a": "lawful",
            "trait_b": "good",
            "alpha_a": 0.0,
            "alpha_b": 0.0,
        },
        "CN": {
            "label": "Chaotic Neutral",
            "trait_a": "chaotic",
            "trait_b": "good",
            "alpha_a": cg_a,
            "alpha_b": 0.0,
        },
        "LE": {
            "label": "Lawful Evil",
            "trait_a": "lawful",
            "trait_b": "evil",
            "alpha_a": le_a,
            "alpha_b": le_b,
        },
        "NE": {
            "label": "Neutral Evil",
            "trait_a": "lawful",
            "trait_b": "evil",
            "alpha_a": 0.0,
            "alpha_b": le_b,
        },
        "CE": {
            "label": "Chaotic Evil",
            "trait_a": "chaotic",
            "trait_b": "evil",
            "alpha_a": ce_a,
            "alpha_b": ce_b,
        },
    }
    return presets

