def _normalize_gates(raw: Any) -> list[bool]:
    if not isinstance(raw, list) or len(raw) != 4:
        raise ValueError("gates must be a list of 4 booleans")
    out: list[bool] = []
    for x in raw:
        if isinstance(x, bool):
            out.append(x)
        elif x in (0, 1):
            out.append(bool(x))
        else:
            raise ValueError(f"invalid gate value: {x!r}")
    return out

