def cmd_eval_answers(args: argparse.Namespace) -> int:
    if args.bundle:
        bundle_path = Path(args.bundle).resolve()
    else:
        if not args.run_id:
            logger.error("Provide --bundle PATH or --run-id RUN_ID.")
            return 1
        bundle_path = (
            PERSONA_RUNS_DIR / args.run_id / "artifacts" / "trait_bundle.json"
