    elif bundle_path.parent.name == "artifacts":
        out_path = (bundle_path.parent.parent / "eval" / "eval_answers.json").resolve()
    else:
        out_path = (bundle_path.parent / "eval_answers.json").resolve()

    limit = args.limit if args.limit > 0 else 0
    try:
