def build_positive_direction(
    v: torch.Tensor,
    layer: int,
    device: torch.device,
    dtype: torch.dtype,
) -> torch.Tensor:
    """D&D / +v steering: return +v[layer] as (1,1,d)."""
    if not (0 <= layer < v.shape[0]):
